        for (String tag : list) {
            if (!tags.existsBySheetIdAndTag(sheetId, tag)) {
                tags.save(new SheetTag(sheetId, tag));
            }
        }
        return list.isEmpty() ? null : String.join(",", list);
    }

    private static String refOf(String ref) {
        return ref == null || ref.isBlank() ? null : ref.trim();
    }
}

